// Why: `i <= n` includes n itself; `i < n` is the classic off-by-one that stops one short.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/for
function sumTo(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) {
    total += i;
  }
  return total;
}

