back:
// Why: Test the most specific case (divisible by both) first, or 15 is caught by the 3
// check. The remainder operator % tells you divisibility.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Remainder
function fizzBuzz(n) {
  const out = [];
  for (let i = 1; i <= n; i++) {
    if (i % 15 === 0) out.push("FizzBuzz");
    else if (i % 3 === 0) out.push("Fizz");
    else if (i % 5 === 0) out.push("Buzz");
    else out.push(String(i));
  }
  return out;
}

