back:
// Why: `return` inside the loop ends it at the first match. Without it you would keep
// overwriting the answer and end up with the last match.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/return
function firstIndexOver(nums, limit) {
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] > limit) return i;
  }
  return -1;
}

